<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\DiscordChannel; use App\Models\DiscordGuild; use App\Models\VoiceEvent; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class VoiceEventController extends Controller { public function store(Request $request): JsonResponse { VoiceEvent::pruneExpired(); $data=$request->validate(['guild_discord_id'=>'required|string|max:255','channel_discord_id'=>'nullable|string|max:255','discord_user_id'=>'nullable|string|max:255','type'=>'required|string|in:voice_join,voice_leave,voice_move,voice_mute,voice_unmute,voice_deafen,voice_undeafen,screen_share_start,screen_share_stop,bot_join,bot_leave','payload'=>'array','occurred_at'=>'nullable|date']); $guild=DiscordGuild::query()->where('discord_id',$data['guild_discord_id'])->first(); $channel=isset($data['channel_discord_id'])?DiscordChannel::query()->voiceBased()->where('discord_id',$data['channel_discord_id'])->firstOrFail():null; $event=VoiceEvent::query()->create(['discord_guild_id'=>$guild?->id,'discord_channel_id'=>$channel?->id,'discord_user_id'=>$data['discord_user_id']??null,'type'=>$data['type'],'payload'=>$data['payload']??[],'occurred_at'=>$data['occurred_at']??now()]); return response()->json(['data'=>['id'=>$event->id]],201); } }
